\usepackage{amsmath}

\title{Problem Set 6: Coupled Oscillators}
\author{PHYS 214 --- Classical Mechanics}
\date{October 2026}

\begin{document}
\maketitle

\section{The Four-Mass Chain}
Four identical masses are joined by five springs of stiffness $k$
between fixed walls. Writing the displacement vector as
$\mathbf{x} = (x_1, x_2, x_3, x_4)^{\mathsf{T}}$, the equations of
motion are $M \ddot{\mathbf{x}} = -K \mathbf{x}$ with mass matrix
$M = m I_4$ and stiffness matrix
\[
K = k
\begin{pmatrix}
2 & -1 & 0 & 0 -1 & 2 & -1 & 0 0 & -1 & 2 & -1 0 & 0 & -1 & 1
\end{pmatrix}
\]
where the off-diagonal entries couple neighbouring masses.

\section{Normal Modes}
The normal mode frequencies follow from
$\det(K - \omega^2 M) = 0$. Show that the lowest mode has adjacent
masses nearly in phase, and sketch the displacement pattern of the
highest mode.

\section{Numerical Check}
With $m = 0.25$~kg and $k = 40$~N/m, compute the four eigenfrequencies
in hertz and compare them with the values measured in the laboratory
session.

\end{document}

